package com.bank.distinctrun;

import java.util.HashSet;
import java.util.Set;
import java.util.logging.Logger;

// Finds the longest distinct operation-code run for National Bank of India.
public class DistinctRunFinder {
    private static final Logger log = Logger.getLogger(DistinctRunFinder.class.getName());

    // Longest substring without repeats via sliding window. O(n), O(alphabet).
    public int longestDistinctRun(String codes) {
        if (codes == null) {
            throw new IllegalArgumentException("codes must not be null");
        }
        Set<Character> window = new HashSet<>();
        int left = 0;
        int best = 0;
        for (int right = 0; right < codes.length(); right++) {
            char c = codes.charAt(right);
            // Shrink from the left until the duplicate is removed.
            while (window.contains(c)) {
                window.remove(codes.charAt(left));
                left++;
            }
            window.add(c);                         // add the new unique char
            int width = right - left + 1;
            if (width > best) {
                best = width;                      // widest all-unique window
            }
        }
        final int result = best;
        log.info(() -> "Longest distinct run = " + result);
        return best;
    }
}
