package com.bank.distinctrun;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

// Runnable demo: longest distinct operation-code run.
public class DistinctRunDemo {
    private static final Logger log = Logger.getLogger(DistinctRunDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        DistinctRunFinder finder = new DistinctRunFinder();

        log.info(() -> "Run = " + finder.longestDistinctRun("abcabcbb")); // 3 ("abc")
        log.info(() -> "Run = " + finder.longestDistinctRun("bbbbb"));    // 1 ("b")
        log.info(() -> "Run = " + finder.longestDistinctRun("pwwkew"));   // 3 ("wke")
    }
}
